const markReplayRunning = `-- name: MarkReplayRunning :execrows
UPDATE app.replay_attempts r
SET state = 'running', started_at = COALESCE(r.started_at, now()), updated_at = now()
WHERE r.id = $1 AND r.state IN ('queued', 'running')
  AND EXISTS (SELECT 1 FROM app.jobs j WHERE j.id = $2 AND j.lease_owner = $3 AND j.state = 'running')
`

type MarkReplayRunningParams struct {
	ID         pgtype.UUID
	JobID      pgtype.UUID
	LeaseOwner pgtype.Text
}

func (q *Queries) MarkReplayRunning(ctx context.Context, arg MarkReplayRunningParams) (int64, error) {
	result, err := q.db.Exec(ctx, markReplayRunning, arg.ID, arg.JobID, arg.LeaseOwner)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const notifyJobs = `-- name: NotifyJobs :exec
SELECT pg_notify('replay_jobs', '')
`

// Wakes idle workers; they also poll, so a lost notification only delays.
func (q *Queries) NotifyJobs(ctx context.Context) error {
	_, err := q.db.Exec(ctx, notifyJobs)
	return err
}

const reapExpiredJobs = `-- name: ReapExpiredJobs :many
UPDATE app.jobs
SET state = CASE WHEN attempts >= max_attempts THEN 'dead' ELSE 'queued' END,
    lease_owner = NULL, lease_expires_at = NULL, run_at = now(), last_error = 'lease_expired', updated_at = now()
WHERE state = 'running' AND lease_expires_at < now()
RETURNING id, kind, state, payload
`

type ReapExpiredJobsRow struct {
	ID      pgtype.UUID
	Kind    string
	State   string
	Payload []byte
}

// Expired leases go back to the queue, or to dead after max_attempts claims.
func (q *Queries) ReapExpiredJobs(ctx context.Context) ([]ReapExpiredJobsRow, error) {
	rows, err := q.db.Query(ctx, reapExpiredJobs)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReapExpiredJobsRow{}
	for rows.Next() {
		var i ReapExpiredJobsRow
		if err := rows.Scan(
			&i.ID,
			&i.Kind,
			&i.State,
			&i.Payload,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const upsertWorkerHeartbeat = `-- name: UpsertWorkerHeartbeat :exec

INSERT INTO app.worker_heartbeats (worker_id, outbound_guard, version, seen_at)
VALUES ($1, $2, $3, now())
ON CONFLICT (worker_id) DO UPDATE SET outbound_guard = EXCLUDED.outbound_guard, version = EXCLUDED.version, seen_at = now()
`

type UpsertWorkerHeartbeatParams struct {
	WorkerID      string
	OutboundGuard string
	Version       string
}

// Worker heartbeats.
func (q *Queries) UpsertWorkerHeartbeat(ctx context.Context, arg UpsertWorkerHeartbeatParams) error {
	_, err := q.db.Exec(ctx, upsertWorkerHeartbeat, arg.WorkerID, arg.OutboundGuard, arg.Version)
	return err
}
